-- Safety-critical flags for a tumour-marker test request, independent of the axes.

CREATE TABLE tumor_marker_test_request_grade_flag (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at TIMESTAMPTZ DEFAULT NULL,

    tumor_marker_test_request_grade_id UUID NOT NULL
        REFERENCES tumor_marker_test_request_grade(id) ON DELETE CASCADE,
    flag_id VARCHAR(50) NOT NULL,
    category VARCHAR(40) NOT NULL DEFAULT ''
        CHECK (category IN (
            'suspected-cancer-2ww',
            'inappropriate-screening-use',
            'marker-indication-mismatch',
            'missing-clinical-details',
            'missing-indication',
            'no-marker-selected',
            'other',
            ''
        )),
    priority VARCHAR(10) NOT NULL DEFAULT ''
        CHECK (priority IN ('low', 'medium', 'high', '')),
    description VARCHAR(500) NOT NULL DEFAULT '',
    suggested_action VARCHAR(500) NOT NULL DEFAULT ''
);

CREATE INDEX index_tumor_marker_test_request_grade_flag_grade_id
    ON tumor_marker_test_request_grade_flag(tumor_marker_test_request_grade_id);

CREATE TRIGGER trigger_tumor_marker_test_request_grade_flag_updated_at
    BEFORE UPDATE ON tumor_marker_test_request_grade_flag
    FOR EACH ROW
    EXECUTE FUNCTION set_updated_at();

COMMENT ON TABLE tumor_marker_test_request_grade_flag IS
